"use client";
import { useId } from "react";
import {
  Area,
  ComposedChart,
  Line,
  ResponsiveContainer,
  Tooltip,
  XAxis,
  YAxis,
} from "recharts";
import { useHydratedReducedMotion } from "../../hooks/use-hydrated-reduced-motion";
import { cx } from "../../utils/cx";
import { ChartCard, CURSOR, formatNumber, useChartHover } from "./chart-card";
import { ChartActiveDot } from "./chart-active-dot";
import { LINE_DEMO_RANGES } from "./chart-demo-data";
import {
  type ChartCommonProps,
  type ChartRange,
  chartAxis,
  ink,
  numeric,
  PALETTE,
  PeriodTabs,
  sum,
  useChartRange,
} from "./pro-chart";
export interface LineSeries {
  key: string;
  label: string;
  tone?: number;
  color?: string;
  dashed?: boolean;
}
export interface LinePoint {
  label: string;
  fullLabel?: string;
  [series: string]: string | number | undefined;
}
export interface LineChartRange extends ChartRange {
  data: LinePoint[];
}
export interface LineChartCardProps extends ChartCommonProps {
  data?: LinePoint[];
  series?: LineSeries[];
  ranges?: LineChartRange[];
  shape?: "smooth" | "sharp";
  curve?: "smooth" | "sharp";
  prefix?: string;
  color?: string;
}
export const LINE_DATA: LinePoint[] = LINE_DEMO_RANGES[0]!.data;
const DEMO_RANGES: LineChartRange[] = LINE_DEMO_RANGES;

const SERIES: LineSeries[] = [{ key: "revenue", label: "Revenue" }];
export function LineChartCard({
  data,
  series = SERIES,
  ranges: supplied,
  title = "Revenue",
  shape,
  curve = "smooth",
  prefix = "$",
  color,
  ...props
}: LineChartCardProps = {}) {
  const ranges = supplied ?? (data ? undefined : DEMO_RANGES),
    period = useChartRange(ranges, props.defaultRange, props.onRangeChange),
    points = period.current?.data ?? data ?? LINE_DATA,
    hover = useChartHover(),
    reduced = useHydratedReducedMotion(),
    id = useId();
  const lead = series[0],
    point = hover.activeIndex != null ? points[hover.activeIndex] : undefined,
    value = point
      ? numeric(point[lead?.key ?? ""])
      : (period.current?.headline ??
        props.headline ??
        sum(points.map((p) => numeric(p[lead?.key ?? ""]))));
  const colors = series.map(
    (s, i) =>
      s.color ??
      (s.tone
        ? `var(--color-chart-${s.tone})`
        : i === 0 && color
          ? color
          : ink(i)),
  );
  const change = period.current?.delta ?? props.delta;
  return (
    <ChartCard
      label={point?.fullLabel ?? point?.label ?? title}
      value={value}
      formatValue={props.format ?? ((n) => prefix + formatNumber(n))}
      roundValue={props.format == null}
      pulseKey={hover.activeIndex}
      delta={
        point || change == null
          ? undefined
          : {
              label: `${change > 0 ? "+" : ""}${+(change * 100).toFixed(1)}%`,
              color: change >= 0 ? "lime" : "rose",
            }
      }
      className={cx("w-full", props.className)}
      height={329}
      action={
        ranges && (
          <PeriodTabs
            ranges={ranges}
            selected={period.id}
            onChange={period.select}
          />
        )
      }
    >
      <ResponsiveContainer width="100%" height="100%">
        <ComposedChart
          data={points}
          margin={{ top: 4, right: 6, bottom: 0, left: 0 }}
          {...hover.handlers}
        >
          <defs>
            <linearGradient id={id} x1="0" y1="0" x2="0" y2="1">
              <stop offset="0%" stopColor={colors[0]} stopOpacity={0.35} />
              <stop offset="100%" stopColor={colors[0]} stopOpacity={0} />
            </linearGradient>
          </defs>
          <YAxis
            {...chartAxis}
            width={44}
            domain={[
              0,
              Math.max(
                1,
                ...points.flatMap((p) => series.map((s) => numeric(p[s.key]))),
              ) * 1.1,
            ]}
            tickCount={4}
            tickFormatter={(n) =>
              prefix +
              (Math.abs(n) >= 1000 ? `${Math.round(n / 1000)}K` : String(n))
            }
          />
          <XAxis
            interval="preserveStartEnd"
            {...chartAxis}
            dataKey="label"
            tick={{ ...chartAxis.tick, fontSize: 13 }}
            tickMargin={12}
          />
          <Tooltip content={() => null} cursor={CURSOR} />
          {lead && (
            <Area
              type={(shape ?? curve) === "sharp" ? "linear" : "monotone"}
              dataKey={lead.key}
              fill={`url(#${id})`}
              stroke="none"
              isAnimationActive={!reduced}
              animationDuration={450}
              animationEasing="ease"
            />
          )}
          {series.map((s, i) => (
            <Line
              key={s.key}
              type={(shape ?? curve) === "sharp" ? "linear" : "monotone"}
              dataKey={s.key}
              stroke={
                s.color ??
                (s.tone
                  ? `var(--color-chart-${s.tone}-active)`
                  : i === 0 && color
                    ? color
                    : `var(--color-chart-${PALETTE[i % PALETTE.length]}-active)`)
              }
              strokeWidth={2.5}
              strokeDasharray={s.dashed ? "5 5" : undefined}
              dot={false}
              activeDot={<ChartActiveDot />}
              isAnimationActive={!reduced}
              animationDuration={450}
              animationEasing="ease"
            />
          ))}
        </ComposedChart>
      </ResponsiveContainer>
    </ChartCard>
  );
}
